function solve(input) {
  const nodes = input.nodes;
  const edges = input.edges;
  const n = nodes.length;

  const sortedNodes = nodes.slice().sort();
  const nodeIndex = new Map();
  for (let i = 0; i < n; i++) {
    nodeIndex.set(nodes[i], i);
  }

  const indegree = new Array(n).fill(0);
  const adj = new Array(n);
  for (let i = 0; i < n; i++) {
    adj[i] = [];
  }

  const seenEdges = new Set();
  let hasCycle = false;

  for (let i = 0; i < edges.length; i++) {
    const edge = edges[i];
    const u = nodeIndex.get(edge[0]);
    const v = nodeIndex.get(edge[1]);

    if (u === v) {
      hasCycle = true;
      continue;
    }

    const key = [edge[0], edge[1]];
    if (!seenEdges.has(key)) {
      seenEdges.add(key);
      adj[u].push(v);
      indegree[v]++;
    }
  }

  if (hasCycle) return null;

  const heap = [];

  function push(index) {
    heap.push(index);
    let i = heap.length - 1;

    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (sortedNodes[heap[parent]] <= sortedNodes[heap[i]]) break;
      const temp = heap[parent];
      heap[parent] = heap[i];
      heap[i] = temp;
      i = parent;
    }
  }

  function pop() {
    const top = heap[0];
    const last = heap.pop();

    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;

      while (true) {
        const left = (i << 1) + 1;
        const right = left + 1;
        let smallest = i;

        if (left < heap.length && sortedNodes[heap[left]] < sortedNodes[heap[smallest]]) {
          smallest = left;
        }

        if (right < heap.length && sortedNodes[heap[right]] < sortedNodes[heap[smallest]]) {
          smallest = right;
        }

        if (smallest === i) break;

        const temp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = temp;
        i = smallest;
      }
    }

    return top;
  }

  for (let i = 0; i < n; i++) {
    if (indegree[i] === 0) push(i);
  }

  const order = [];

  while (heap.length > 0) {
    const u = pop();
    order.push(sortedNodes[u]);

    for (let j = 0; j < adj[u].length; j++) {
      const v = adj[u][j];
      indegree[v]--;
      if (indegree[v] === 0) push(v);
    }
  }

  return order.length === n ? order : null;
}

