function solve(input) {
  const cache = new Map();
  const results = [];

  for (let i = 0; i < input.length; i++) {
    const op = input[i];

    if (op.op === "put") {
      const expiry = op.t + op.ttl;
      if (op.t >= expiry) {
        cache.delete(op.key);
      } else {
        cache.set(op.key, { value: op.value, expiry });
      }
    } else if (op.op === "get") {
      const entry = cache.get(op.key);
      if (!entry || op.t >= entry.expiry) {
        results.push(null);
      } else {
        results.push(entry.value);
      }
    } else if (op.op === "delete") {
      cache.delete(op.key);
    }
  }

  return results;
}

