function solve({ document, pointer }) {
  let current = document;

  if (pointer.length === 0) {
    return { found: true, value: current };
  }

  for (const encodedToken of pointer.slice(1).split("/")) {
    const token = encodedToken.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      if (!/^(0|[1-9]\d*)$/.test(token) || !Number.isSafeInteger(Number(token))) {
        return { found: false };
      }

      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return { found: false };
      }

      current = current[token];
    } else if (current !== null && (typeof current === "object" || typeof current === "function")) {
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return { found: false };
      }

      current = current[token];
    } else {
      return { found: false };
    }
  }

  return { found: true, value: current };
}

